<?php require_once '../includes/config.php'; require_role('admin');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$st=$pdo->prepare('UPDATE support_tickets SET status=?,staff_reply=? WHERE id=?');$st->execute([post_str('status'),post_str('reply'),(int)$_POST['id']]);flash('success','Support ticket updated.');redirect('support.php');}$rows=$pdo->query("SELECT t.*,u.name,u.email FROM support_tickets t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC")->fetchAll();$title='Support Tickets';require '../includes/header.php';?><h1 class="section-title">Support Tickets</h1><?php foreach($rows as $r):?><div class="panel p-4 mb-3"><div class="d-flex justify-content-between"><div><strong>#<?=$r['id']?> <?=e($r['subject'])?></strong><div class="text-secondary"><?=e($r['name'])?> · <?=e($r['email'])?></div></div><span class="badge bg-secondary"><?=e($r['status'])?></span></div><p class="mt-3"><?=e($r['message'])?></p><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="col-md-3"><select name="status" class="form-select"><option>open</option><option>in progress</option><option>resolved</option></select></div><div class="col-md-7"><input name="reply" class="form-control" value="<?=e($r['staff_reply'])?>" placeholder="Staff reply"></div><div class="col-md-2"><button class="btn btn-purple w-100">Update</button></div></form></div><?php endforeach;?><?php require '../includes/footer.php'; ?>